UIGameIconImage=function(game){Phaser.Image.call(this,game,0,0,'gameicon',0);this.anchor.setTo(0.5,0.5);this.gameModeIcon=this.addChild(new Phaser.Sprite(this.game,0,0,'gamemodeicon',0));this.gameModeIcon.anchor.setTo(0.5,0.5);this.tankIconGroup=this.game.add.group(this);this.tankIcons={};for(var i=0;i<UIConstants.GAME_ICON_TANK_COUNT;++i){this.tankIconGroup.add(new UITankIconImage(this.game,true,UIConstants.TANK_ICON_SIZES.SMALL));}this.tankNameGroup=this.game.add.group(this);for(var i=0;i<UIConstants.GAME_ICON_TANK_COUNT;++i){this.tankNameGroup.add(new UITankIconNameGroup(this.game,UIConstants.TANK_ICON_WIDTH_SMALL,true));}this.tankIconPlacementsTaken=[];for(var i=0;i<UIConstants.GAME_ICON_TANK_COUNT;++i){this.tankIconPlacementsTaken.push(false);}this.removeTween=null;this.scale.set(0.0,0.0);this.kill();this.log=Log.create('UIGameIconImage');};UIGameIconImage.prototype=Object.create(Phaser.Image.prototype);UIGameIconImage.prototype.constructor=UIGameIconImage;UIGameIconImage.prototype.update=function(){if(!this.exists){return;}for(var tankIconSpriteId in this.tankIcons){this.tankIcons[tankIconSpriteId].icon.update();this.tankIcons[tankIconSpriteId].name.update();}};UIGameIconImage.prototype.getTankIcons=function(){return this.tankIcons;};UIGameIconImage.prototype.spawn=function(x,y,gameState,favouriteActiveQueuedCounts){this.reset(x,y);this.gameId=gameState.getId();this.mode=gameState.getMode();this.ranked=gameState.getRanked();this.symmetric=gameState.getSymmetric();this.premium=gameState.getPremium();this.playerStates=gameState.getPlayerStates();this.favouriteActiveQueuedCounts=favouriteActiveQueuedCounts;this._updateUI();var delay=50+Math.random()*200;if(this.removeTween){this.removeTween.stop();}this.game.add.tween(this.scale).to({x:UIConstants.ASSET_SCALE,y:UIConstants.ASSET_SCALE},UIConstants.ELEMENT_POP_IN_TIME,Phaser.Easing.Back.Out,true,delay);};UIGameIconImage.prototype.refresh=function(gameState,favouriteActiveQueuedCounts){this.mode=gameState.getMode();this.ranked=gameState.getRanked();this.symmetric=gameState.getSymmetric();this.premium=gameState.getPremium();this.playerStates=gameState.getPlayerStates();this.favouriteActiveQueuedCounts=favouriteActiveQueuedCounts;this._updateUI();};UIGameIconImage.prototype._updateUI=function(){this.frame=(this.symmetric?1:0)*2+(this.premium?1:0);var iconFrame=UIConstants.GAME_MODE_NAME_INFO[this.mode].ICON;if(iconFrame<0){this.gameModeIcon.visible=false;}else{this.gameModeIcon.frame=iconFrame*2+(this.premium?1:0);this.gameModeIcon.visible=true;}for(var tankIconSpriteId in this.tankIcons){var tankIconStillNeeded=false;for(var i=0;i<this.playerStates.length;++i){if(tankIconSpriteId==this.playerStates[i].getPlayerId()){tankIconStillNeeded=true;break;}}if(!tankIconStillNeeded){this.tankIcons[tankIconSpriteId].icon.remove();this.tankIcons[tankIconSpriteId].name.remove();this.tankIconPlacementsTaken[this.tankIcons[tankIconSpriteId].placement]=false;delete this.tankIcons[tankIconSpriteId];}}for(var i=0;i<this.playerStates.length;++i){if(this.playerStates[i].getPlayerId()in this.tankIcons){this.tankIcons[this.playerStates[i].getPlayerId()].icon.refresh();this.tankIcons[this.playerStates[i].getPlayerId()].name.refresh(undefined,undefined,undefined,this.ranked);}else{var tankIconSprite=this.tankIconGroup.getFirstExists(false);var tankNameSprite=this.tankNameGroup.getFirstExists(false);if(tankIconSprite&&tankNameSprite){var availablePosition=0;for(var j=0;j<UIConstants.GAME_ICON_TANK_COUNT;++j){if(!this.tankIconPlacementsTaken[j]){availablePosition=j;break;}}this.tankIconPlacementsTaken[availablePosition]=true;this.tankIcons[this.playerStates[i].getPlayerId()]={icon:tankIconSprite,name:tankNameSprite,placement:availablePosition};tankIconSprite.spawn(UIConstants.TANK_ICON_PLACEMENTS[availablePosition].x,UIConstants.TANK_ICON_PLACEMENTS[availablePosition].y,this.playerStates[i].getPlayerId(),UIConstants.TANK_ICON_PLACEMENTS[availablePosition].flipped,true);tankNameSprite.spawn(UIConstants.TANK_NAME_PLACEMENTS[availablePosition].x,UIConstants.TANK_NAME_PLACEMENTS[availablePosition].y,this.playerStates[i].getPlayerId(),undefined,this.ranked);}else{this.log.error("Could not create tank icon sprite or tank name sprite. No sprite available.");}}}};UIGameIconImage.prototype.remove=function(){this.removeTween=this.game.add.tween(this.scale).to({x:0.0,y:0.0},UIConstants.ELEMENT_GLIDE_OUT_TIME,Phaser.Easing.Linear.None,true);this.removeTween.onComplete.add(function(){this.kill();},this);this.tankIconGroup.callAll('remove');this.tankNameGroup.callAll('remove');this.tankIcons={};for(var i=0;i<UIConstants.GAME_ICON_TANK_COUNT;++i){this.tankIconPlacementsTaken[i]=false;}};UIGameIconImage.prototype.retire=function(){this.kill();this.tankIconGroup.callAll('retire');this.tankNameGroup.callAll('retire');};